// Reading-focused interface for AIBEEP; all figures derive from local records.
let featuredCategory="", digestSelected="", publicItems=[];
// Published content is shared by all visitors. Local storage is only for personal bookmarks.
const cleanRecords=()=>[...publicItems].filter(x=>x&&x.title&&x.url&&safeUrl(x.url)).sort((a,b)=>new Date(b.addedAt)-new Date(a.addedAt));
const matchText=(x,q)=>!q||[x.title,x.source,x.summary,x.category].join(" ").toLowerCase().includes(q.toLowerCase());
const dateOf=x=>{const d=new Date(x.addedAt);return Number.isNaN(d.getTime())?new Date():d};
const timeOf=x=>dateOf(x).toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit",hour12:false});
const dayOf=x=>dateOf(x).toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"});
const summaryOf=x=>String(x.summary||"").slice(0,500);
function articleCard(x){return `<article class="timeline-entry"><time class="timeline-time">${esc(timeOf(x))}</time><div class="story-card"><div class="story-top"><div class="story-meta"><span>${esc(x.source)}</span><span class="story-badge">${esc(x.category)}</span><span>${esc(dayOf(x))}</span></div></div><h3>${esc(x.title)}</h3><p>${esc(summaryOf(x))}</p><div class="story-bottom"><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">阅读原始来源 ↗</a><button class="btn reader-bookmark" data-bookmark="${esc(x.id)}">${isBookmarked(x.id)?"★ 已收藏":"☆ 收藏"}</button></div></div></article>`}
const BOOKMARKS_KEY="aibeep-reader-bookmarks-v1";
function bookmarkIds(){try{return JSON.parse(localStorage.getItem(BOOKMARKS_KEY))||[]}catch{return []}}
function isBookmarked(id){return bookmarkIds().includes(id)}
function emptyEditorial(label){return `<div class="empty-panel"><strong>${label}</strong><p>内容正在整理中，稍后再来看看。</p></div>`}
function mountAddButtons(){document.querySelectorAll(".add").forEach(b=>b.onclick=()=>$("#overlay").classList.add("show"))}
function renderEditorial(){const items=cleanRecords(),fq=$("#qFeatured").value.trim();const featured=items.filter(x=>(!featuredCategory||x.category===featuredCategory)&&matchText(x,fq));$("#featuredCount").textContent=`${featured.length} 条`;
 $("#featuredSpotlight").innerHTML=items.length?items.slice(0,3).map((x,i)=>`<a class="spotlight-card" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer"><span class="spotlight-label">${String(i+1).padStart(2,"0")} · ${esc(x.category)}</span><strong>${esc(x.title)}</strong><span class="spotlight-source">${esc(x.source)} · ${esc(dayOf(x))} ↗</span></a>`).join(""):`<div class="spotlight-card spotlight-placeholder"><span class="spotlight-label">01 · 广告平台</span><strong>平台政策与广告产品变化</strong><span class="spotlight-source">关注投放规则、成本与流量机制</span></div><div class="spotlight-card spotlight-placeholder"><span class="spotlight-label">02 · AI 营销</span><strong>AI 工具如何进入实际营销链路</strong><span class="spotlight-source">关注工具更新与真实应用</span></div><div class="spotlight-card spotlight-placeholder"><span class="spotlight-label">03 · 企业获客</span><strong>从线索成本走向有效转化</strong><span class="spotlight-source">关注线索质量、销售承接和 ROI</span></div>`;
 $("#featuredFeed").innerHTML=featured.length?featured.map(articleCard).join(""):emptyEditorial(items.length?"没有符合筛选条件的内容":"精选内容正在准备中");
 $("#featuredRank").innerHTML=items.length?items.slice(0,5).map((x,i)=>`<div class="rank-row"><span class="rank-number">${i+1}</span><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a><small>${esc(x.category)} · ${esc(x.source)}</small></div>`).join(""):'<div class="rank-muted">录入情报后，这里显示最近关注的 5 条内容。</div>';
 const all=items.filter(x=>(!$("#fIntel").value||x.category===$("#fIntel").value)&&matchText(x,$("#qIntel").value.trim()));$("#allCount").textContent=`${all.length} 条`;$("#allIntel").innerHTML=all.length?all.map(articleCard).join(""):emptyEditorial(items.length?"没有符合筛选条件的内容":"动态内容正在准备中");renderBookmarks(items);
 renderHot(items);renderDigest(items);renderThemes(items);mountAddButtons()}
function renderHot(items){if(!items.length){$("#hotBoard").innerHTML=emptyEditorial("真实热点数据尚未接入");return}const first=items[0],mini=items.slice(1,3);$("#hotBoard").innerHTML=`<div class="hot-lead"><article class="hot-main"><div><span class="hot-number">NO.01 · 近期收录</span><h2>${esc(first.title)}</h2><p>${esc(summaryOf(first))}</p></div><div class="story-bottom"><span>${esc(first.source)} · ${esc(first.category)}</span><a href="${esc(first.url)}" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></div></article><div class="hot-aside">${mini.length?mini.map((x,i)=>`<article class="hot-minicard"><span class="hot-number">NO.0${i+2} · 近期收录</span><h3>${esc(x.title)}</h3><p>${esc(x.source)}</p></article>`).join(""):'<div class="empty-panel"><strong>等待更多资料</strong><p>多录入几条信息后，这里会显示近期关注。</p></div>'}</div></div><div class="timeline-head"><h2>继续看</h2><span>按录入时间排序</span></div><div class="hot-list">${items.slice(3,12).map((x,i)=>`<div class="rank-row"><span class="rank-number">${String(i+4).padStart(2,"0")}</span><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a><small>${esc(x.source)}</small></div>`).join("")||'<div class="rank-muted">暂无更多记录</div>'}</div>`}
function renderBookmarks(items){const saved=new Set(bookmarkIds());const chosen=items.filter(x=>saved.has(x.id));$("#topicList").innerHTML=chosen.length?`<div class="timeline">${chosen.map(articleCard).join("")}</div>`:`<div class="empty-panel"><strong>还没有收藏内容</strong><p>在「精选」或「全部动态」里点击收藏，文章就会保存在这里。</p></div>`}
function renderDigest(items){const now=new Date(),days=[...new Set(items.map(dayOf))];if(!digestSelected||!days.includes(digestSelected))digestSelected=days[0]||now.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"});const chosen=items.filter(x=>dayOf(x)===digestSelected);const d=chosen.length?dateOf(chosen[0]):now;$("#digestToday").textContent=d.toLocaleDateString("zh-CN",{year:"numeric",month:"long",day:"numeric",weekday:"long"});$("#digestDay").textContent=d.getDate();$("#digestMonth").textContent=d.toLocaleDateString("zh-CN",{year:"numeric",month:"long"});$("#digestStories").textContent=chosen.length;
 $("#digestDates").innerHTML=days.length?days.map(x=>`<button type="button" class="archive-item ${x===digestSelected?"active":""}" data-digest="${esc(x)}">${esc(x)} <span>· ${items.filter(y=>dayOf(y)===x).length} 条</span></button>`).join(""):'<p style="color:#89999a;font-size:12px;line-height:1.8">尚无可整理的资料，先添加一条情报。</p>';
 $("#digestStoriesList").innerHTML=chosen.length?chosen.map((x,i)=>`<article class="digest-article"><div><span class="overline">${String(i+1).padStart(2,"0")} · ${esc(x.category)}</span><h2>${esc(x.title)}</h2><p>${esc(summaryOf(x))}</p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">阅读原始资料 ↗</a></div><aside><h3>信息来源</h3><p>${esc(x.source)}</p><h3>录入时间</h3><p>${esc(timeOf(x))}</p></aside></article>`).join(""):emptyEditorial("这一天还没有可以成刊的资料")}
const themes=[{heading:"广告平台",subtitle:"平台政策、产品和广告工具",list:["腾讯广告","巨量引擎","巨量千川","小红书聚光","快手磁力","百度营销","Google Ads","Meta Ads"]},{heading:"营销与增长",subtitle:"围绕真实业务问题追踪",list:["AI 营销","企业获客","线索质量","素材策略","私域增长","营销自动化","投放复盘","转化率优化"]},{heading:"内容类型",subtitle:"从情报到可执行选题",list:["官方公告","行业动态","案例与数据","实操教程","产品更新","研究报告","工具实践","个人观点"]}];
function themeMatches(x,label){const fields=[x.title,x.summary,x.source,x.category].join(" ").toLowerCase();const alias={"快手磁力":["磁力","快手"],"Meta Ads":["meta","facebook"],"Google Ads":["google","谷歌"],"AI 营销":["ai营销","ai 营销","人工智能","营销ai"],"私域增长":["私域","公众号","社群"],"投放复盘":["复盘","投放"],"官方公告":["公告","官方"],"工具实践":["工具","工作流"],"个人观点":["观点"],"案例与数据":["案例与数据","案例","数据"],"线索质量":["线索"],"产品更新":["更新","发布"]};return (alias[label]||[label]).some(w=>fields.includes(w.toLowerCase()))}
function renderThemes(items){$("#themeGroups").innerHTML=themes.map(g=>`<section class="theme-section"><h2>${esc(g.heading)} <small>${esc(g.subtitle)}</small></h2><div class="theme-grid">${g.list.map(label=>{const found=items.filter(x=>themeMatches(x,label)),x=found[0];return `<button type="button" class="theme-card" data-theme="${esc(label)}"><h3>${esc(label)}</h3><p>${x?esc(x.title):"暂无资料，等待收录"}</p><div class="theme-bottom"><span>${found.length?"最新记录 · "+esc(dayOf(x)):"尚未收录"}</span><span>${found.length} 条</span></div></button>`}).join("")}</div></section>`).join("")}
$("#qFeatured").addEventListener("input",renderEditorial);
$$("#featuredFilters .pill").forEach(btn=>btn.addEventListener("click",()=>{featuredCategory=btn.dataset.filter;$$("#featuredFilters .pill").forEach(b=>b.classList.toggle("active",b===btn));renderEditorial()}));
$$("#allFilters .pill").forEach(btn=>btn.addEventListener("click",()=>{$("#fIntel").value=btn.dataset.category;$$("#allFilters .pill").forEach(b=>b.classList.toggle("active",b===btn));render()}));
document.addEventListener("click",e=>{const d=e.target.closest("[data-digest]"),t=e.target.closest("[data-theme]");if(d){digestSelected=d.dataset.digest;renderDigest(cleanRecords())}if(t){const label=t.dataset.theme;const found=cleanRecords().filter(x=>themeMatches(x,label));go("intel");$("#qIntel").value=label;$$("#allFilters .pill").forEach(b=>b.classList.toggle("active",b.dataset.category===""));$("#fIntel").value="";if(!found.length){toast("这个主题暂无情报，可以先录入相关资料")}renderThemeSearch(label,found)}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-bookmark]");if(!b)return;const id=b.dataset.bookmark;const ids=new Set(bookmarkIds());ids.has(id)?ids.delete(id):ids.add(id);localStorage.setItem(BOOKMARKS_KEY,JSON.stringify([...ids]));renderEditorial();toast(ids.has(id)?"已收藏文章":"已取消收藏")});
function renderThemeSearch(label,found){$("#allCount").textContent=`主题「${label}」 · ${found.length} 条`;$("#allIntel").innerHTML=found.length?found.map(articleCard).join(""):emptyEditorial("这个主题暂无资料")}
$("#qIntel").addEventListener("input",()=>{$$("#allFilters .pill").forEach(b=>b.classList.toggle("active",b.dataset.category===$("#fIntel").value))});
$("#copyFeedback").onclick=async()=>{const content=$("#feedbackBody").value.trim();if(!content)return toast("先写下想修改的地方");const value=`AIBEEP 界面反馈\n页面：${$("#feedbackPage").value.trim()||"未指定"}\n问题或建议：${content}`;try{await navigator.clipboard.writeText(value);toast("已复制反馈，可粘贴到聊天中")}catch{toast("复制失败，请手动选择文字复制")}};
renderEditorial();
const contentEndpoint=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?"/api/content":"content.json";
fetch(contentEndpoint,{cache:"no-cache"}).then(response=>{if(!response.ok)throw Error("Content unavailable");return response.json()}).catch(()=>fetch("content.json",{cache:"no-cache"}).then(r=>{if(!r.ok)throw Error("Content unavailable");return r.json()})).then(data=>{if(!Array.isArray(data.items))throw Error("Invalid content");publicItems=data.items.filter(item=>item&&typeof item.title==="string"&&typeof item.summary==="string"&&safeUrl(item.url)).map(item=>({...item,saved:false}));renderEditorial();window.dispatchEvent(new Event("aibeep:content"))}).catch(()=>{const node=$("#featuredFeed");if(node)node.innerHTML=emptyEditorial("资讯暂时无法加载，请稍后刷新页面")});
